applicableItems.value:
reqs  = {{.Initial_Applicable_Items_Rule.output[0]}};
conds = {{.Conditional_Applicable_Items_Resolution_Rule.output}};

var SKIP = ["defaultOutputData", "rowError", "rowId"];
var applicable = {};

for (var k in reqs) {
  if (SKIP.indexOf(k) === -1) { applicable[k] = String(reqs[k]).toLowerCase(); }
}

var MAP = {
  "fee_posting": "Fee_posting",
  "rate_adjustment": "Rate_adjustment_evidence",
  "suspense_evidence": "Suspense_posting_evidence",
  "loan_history": "Loan_history_posting_confirmation",
  "bill_notice": "Bill_payment_notice"
};

for (var i = 0; i < conds.length; i++) {
  var r = conds[i].output[0];
  var key = MAP[r.item];
  if (key && applicable[key] === "conditional") {
    applicable[key] = String(r.requirement).toLowerCase();
  }
}

for (var k in applicable) {
  if (applicable[k] === "conditional") { throw new Error("Unresolved: " + k); }
}

applicable;

