for (var i = 0; i < n7j.length; i++) { if (n7j[i].unattested) { low_trust = true; } }

return {
  any_missing: n7e.length > 0,
  any_omission: n7d.length > 0,
  out_of_balance: n7f,
  any_variance: n7g.length > 0,
  due_date_advanced: n7h,
  unexpected_unjustified: unexpected_unjustified,
  any_low_trust_unattested: low_trust
};
}
