out_of_balance_and_variance_and_due_date.value:
function balance(n4){
  for (var i = 0; i < n4.length; i++) {
  var o = n4[i].output;
  for (var j = 0; j < o.length; j++) {
    if (String(o[j].type).toLowerCase() === "balance" && o[j].variance !== 0) { return true; }
  }
}
return false;
}
function variance(n4){
  var out = [];
for (var i = 0; i < n4.length; i++) {
  var o = n4[i].output;
  for (var j = 0; j < o.length; j++) {
    var t = String(o[j].type).toLowerCase();
    if (t === "balance" || t === "due date") { continue; }
    if (String(o[j].result).toLowerCase() === "variance") {
      out.push({ comparison: o[j].type, variance: o[j].variance });
    }
  }
}
return out;
}
function due_date_advanced(n4){
  for (var i = 0; i < n4.length; i++) {
  var o = n4[i].output;
  for (var j = 0; j < o.length; j++) {
    if (String(o[j].type).toLowerCase() === "due date"
        && String(o[j].result).toLowerCase() === "violation") { return true; }
  }
}
return false;
}

result = {
out_of_balance : balance({{.Source_VS_System_Check_Rule.output}}),
variance : variance({{.Source_VS_System_Check_Rule.output}}),
due_date_adv : due_date_advanced({{.Source_VS_System_Check_Rule.output}})}
result

presence_of_items.value:
p = {{.Trigger.payment_packet}};

var TC_PAYMENT        = {{.globalVar.TC_PAYMENT}};
var TC_DEPOSIT_CREDIT = {{.globalVar.TC_DEPOSIT_CREDIT}};
var TC_FEE_SET        = {{.globalVar.TC_FEE_SET}};
var TC_SUSPENSE       ={{.globalVar.TC_SUSPENSE}};

function hasCode(list, codes) {
  for (var i = 0; i < list.length; i++) {
    if (codes.indexOf(list[i].transaction_code) !== -1) { return true; }
  }
  return false;
}

result = {
  "Loan_posting_credit_entry_to_the_loan": hasCode(p.postings, TC_PAYMENT),
  "Bill_payment_notice": p.notice != null && p.notice.present === true,
  "Interest_calculation_worksheet": p.interest_worksheet != null,
  "Deposit_credit_wire_clearing_entry": hasCode(p.postings, TC_DEPOSIT_CREDIT),
  "Fee_posting": hasCode(p.postings, TC_FEE_SET),
  "Loan_history_posting_confirmation": p.loan_history_present === true,
  "Rate_adjustment_evidence": p.loan.rate_before !== p.loan.rate_after,
  "GL_journal_cross_application_movement": p.gl_totals != null,
  "Suspense_posting_evidence": hasCode(p.postings, TC_SUSPENSE)
};
result

trust_flags.value:
function trust_flags(n6){
  function listHas(list, item) {
  if (list == null) { return false; }
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].item).toLowerCase() === String(item).toLowerCase()) { return true; }
  }
  return false;
}

var out = [];
for (var i = 0; i < n6.length; i++) {
  var r = n6[i].output[0];
  out.push({
    item: r.type,
    trust_level: r.trust,
    action_required: r.action_required || null,
    unattested: String(r.trust).toLowerCase() === "low" && !listHas(trigger.attestations, r.type)
  });
}
return out;
}
trust_flags({{.Provenance_And_Trust_Deriving_Rule.output}})

unexpected.value:
function unexpected(n5,trigger){
  function listHas(list, item) {
  if (list == null) { return false; }
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].item).toLowerCase() === String(item).toLowerCase()) { return true; }
  }
  return false;
}

var out = [];
for (var i = 0; i < n5.length; i++) {
  var r = n5[i].output[0];
  if (String(r.result).toLowerCase() === "unexpected item" || String(r.result).toLowerCase()=== "justification required") {
    out.push({ item: r.type, justified: listHas(trigger.justifications, r.type) });
  }
}
return out;
}
